// One pending record per grabbed item. The id is whatever the *arr app
// will send back in its webhook: episodeId for Sonarr, movieId for Radarr.
const b = $input.first().json.body ?? $input.first().json;
const app = String(b.app || 'sonarr').toLowerCase();
const id = String(b.id ?? '');
if (!id) throw new Error('track-download: id is required');
const record = {
  app,
  id,
  title: b.title ?? '',
  chat: b.chat ?? '',
  channel: b.channel ?? 'whatsapp',
  requestedBy: b.requestedBy ?? '',
  note: b.note ?? '',
  startedAt: new Date().toISOString(),
};
return [{ json: { key: `n8n:openclaw:dl:${app}:${id}`, record, value: JSON.stringify(record) } }];

// Sonarr and Radarr post the same envelope shape: eventType plus series/
// episodes or movie. Reduce it to {app, id, kind, text} and let the next
// nodes decide whether anyone was waiting for it.
const b = $input.first().json.body ?? $input.first().json;
const ev = String(b.eventType || '');
const isSonarr = Boolean(b.series || b.episodes);
const app = isSonarr ? 'sonarr' : 'radarr';

let id = '';
let label = '';
if (isSonarr) {
  const ep = (b.episodes && b.episodes[0]) || {};
  id = String(ep.id ?? '');
  const s = String(ep.seasonNumber ?? '').padStart(2, '0');
  const e = String(ep.episodeNumber ?? '').padStart(2, '0');
  label = `${b.series?.title ?? 'Unknown'} S${s}E${e}${ep.title ? ' - ' + ep.title : ''}`;
} else {
  id = String(b.movie?.id ?? '');
  label = `${b.movie?.title ?? 'Unknown'}${b.movie?.year ? ' (' + b.movie.year + ')' : ''}`;
}

// Poster: the public TVDB/TMDB URL from the payload. OpenClaw fetches it
// itself, and its SSRF guard refuses internal hosts like sonarr:8989.
const images = (isSonarr ? b.series?.images : b.movie?.images) || [];
const poster = images.find(i => i.coverType === 'poster')?.remoteUrl || '';
const show = isSonarr ? (b.series?.title ?? 'Unknown') : label;

// Only these three change a pending record's fate. Test/Grab/others are
// acknowledged and dropped.
const kind =
  ev === 'Download' || ev === 'ImportComplete' ? 'done' :
  ev === 'ManualInteractionRequired' ? 'blocked' :
  'ignore';

const quality = b.episodeFile?.quality || b.movieFile?.quality || b.release?.quality || '';
const size = b.episodeFile?.size || b.movieFile?.size || b.release?.size || 0;
const sizeGb = size ? (size / 1073741824).toFixed(1) + ' GB' : '';

return [{ json: { app, id, kind, eventType: ev, label, show, poster, quality, sizeGb, key: `n8n:openclaw:dl:${app}:${id}` } }];

// Templated, not generated: no model call on this path.
const ev = $('parse arr event').first().json;
const raw = $input.first().json.pending;
// The Redis node may hand back the stored JSON already parsed.
const rec = typeof raw === 'string' ? JSON.parse(raw) : (raw || {});
const bits = [ev.quality, ev.sizeGb].filter(Boolean).join(', ');

const text = ev.kind === 'done'
  ? `Downloaded: ${ev.label}${bits ? ' (' + bits + ')' : ''}. Ready to watch.`
  : `Import blocked: ${ev.label}. The download finished but ${ev.app} will not import it (usually a bad release). Ask me to remove and blocklist it, then search again.`;

return [{ json: { key: ev.key, channel: rec.channel || 'whatsapp', to: rec.chat, message: text, media: ev.poster } }];

// Nothing here calls Sonarr: completion and import-blocked both arrive as
// webhooks, so the only case left is "no event ever came". Report once at
// STALE_HOURS and close the record; the 48h TTL is the backstop.
const STALE_HOURS = Number($env.ARR_WATCH_STALE_HOURS || 6);
const out = [];
for (const item of $input.all()) {
  for (const [key, raw] of Object.entries(item.json)) {
    if (!key.startsWith('n8n:openclaw:dl:')) continue;
    let rec;
    try { rec = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch { continue; }
    if (!rec || !rec.startedAt || !rec.chat) continue;
    const ageH = (Date.now() - Date.parse(rec.startedAt)) / 3600000;
    if (ageH < STALE_HOURS) continue;
    out.push({ json: {
      key,
      channel: rec.channel || 'whatsapp',
      to: rec.chat,
      message: `Still not finished after ${Math.floor(ageH)}h: ${rec.title || rec.app + ' ' + rec.id}. It may be stalled - ask me to check the queue.`,
    }});
  }
}
return out;

// Untracked imports: things Sonarr/Radarr grabbed on their own (RSS, a
// monitored sequel, an upgrade). Templated - no model call. One message per
// show or movie, sent as its poster with the episodes as the caption; the
// headline rides on the first one. Blocked imports follow as plain text.
const raw = $input.first().json.items || [];
const rows = raw.map(r => { try { return typeof r === 'string' ? JSON.parse(r) : r; } catch { return null; } }).filter(Boolean);
if (!rows.length) return [];

const done = rows.filter(r => r.kind === 'done');
const blocked = rows.filter(r => r.kind === 'blocked');
const bits = r => r.quality || r.sizeGb ? ' (' + [r.quality, r.sizeGb].filter(Boolean).join(', ') + ')' : '';
const line = r => `- ${r.label}${bits(r)}`;

// Group by show so a binge is one poster, not eight. Rows logged before
// posters existed have no show/poster and stand alone as text.
const groups = new Map();
for (const r of done) {
  const show = r.show || r.label;
  if (!groups.has(show)) groups.set(show, { poster: '', rows: [] });
  const g = groups.get(show);
  g.rows.push(r);
  g.poster = g.poster || r.poster || '';
}

const out = [];
const send = (message, media) => out.push({ json: { channel: 'whatsapp', to: $env.DIGEST_CHAT, message, media: media || '' } });

let headline = done.length ? `${done.length} new ${done.length === 1 ? 'thing' : 'things'} landed today:\n\n` : '';
for (const [show, g] of groups) {
  // Episodes: show name once, then "- S02E02 - Song 2 (...)". Movies: one line.
  const isShow = g.rows[0].app === 'sonarr' && g.rows[0].show;
  const lines = g.rows.map(r => isShow && r.label.startsWith(show + ' ')
    ? `- ${r.label.slice(show.length + 1)}${bits(r)}` : `${r.label}${bits(r)}`);
  send(headline + (isShow ? show + '\n' : '') + lines.join('\n'), g.poster);
  headline = '';
}
if (blocked.length) send([`${blocked.length} could not be imported:`, ...blocked.map(line)].join('\n'));

return out;
